# Generated from SymPy outputs (reference commit 86150a81); each expected
# string is what SymPy prints for the same input. Only inputs on which the
# port agrees with SymPy are listed; the tracker records the others.

skip_unless_full_tests()

test_that("hyperexpand matches SymPy on hypergeometric functions", {
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s))), want, label = s)
  chk("hyper([], [], z)", hyperexpand, "exp(z)")
  chk("hyper([1, 1], [2], -z)*z", hyperexpand, "log(z + 1)")
  chk("hyper([], [Rational(1, 2)], -z**2/4)", hyperexpand, "cos(z)")
  chk("z*hyper([], [Rational(3, 2)], -z**2/4)", hyperexpand, "sin(z)")
  chk("hyper([Rational(1, 2), Rational(1, 2)], [Rational(3, 2)], z**2)*z", hyperexpand, "asin(z)")
  chk("hyper([], [-1], z)", hyperexpand, "oo")
  chk("hyper([-2], [-1], z)", hyperexpand, "oo")
  chk("hyper([0, 0], [-1], z)", hyperexpand, "1")
  chk("hyper((-1, 1), (-2,), z)", hyperexpand, "z/2 + 1")
  chk("hyper([2], [a], z)", hyperexpand, "a + z^(1 - a)*(-a^2 + 3*a + z*(a - 1) - 2)*exp(z)*lowergamma(a - 1, z) - 1")
  chk("hyper([1, 2], [3], z)", hyperexpand, "-2/z - 2*log(1 - z)/z^2")
  chk("hyper([Rational(1, 2), 2], [Rational(3, 2)], z)", hyperexpand, "-1/(2*z - 2) + atanh(sqrt(z))/(2*sqrt(z))")
  chk("hyper([Rational(1, 2), Rational(1, 2)], [Rational(5, 2)], z)", hyperexpand, "(3/4 - 3*z/4)/(z*sqrt(1 - z)) + (6*z - 3)*asin(sqrt(z))/(4*z^(3/2))")
  chk("hyper([1, 2], [Rational(3, 2)], z)", hyperexpand, "-1/(2*z - 2) - asin(sqrt(z))/(sqrt(z)*sqrt(1 - z)*(2*z - 2))")
  chk("hyper([Rational(-1, 2) - 1, 1, 2], [Rational(1, 2), 3], z)", hyperexpand, "sqrt(z)*(6*z/7 - 6/5)*atanh(sqrt(z)) + (-6*z^2/7 + 32*z/35 - 6/35)/z - 6*log(1 - z)/(35*z^2)")
  chk("hyper([1 + Rational(1, 2), 1, 1], [2, 2], z)", hyperexpand, "-4*log(sqrt(1 - z)/2 + 1/2)/z")
  chk("hyper([2], [b, 1], z)", hyperexpand, "z^(1/2 - b/2)*besseli(b - 1, 2*sqrt(z))*gamma(b) + z^(1 - b/2)*besseli(b, 2*sqrt(z))*gamma(b)")
  chk("hyper([a, Rational(1, 2) + a], [Rational(1, 2)], z)", hyperexpand, "1/(2*(sqrt(z) + 1)^(2*a)) + 1/(2*(1 - sqrt(z))^(2*a))")
  chk("hyper([a, Rational(-1, 2) + a], [2*a], z)", hyperexpand, "2^(2*a - 1)*(sqrt(1 - z) + 1)^(1 - 2*a)")
  chk("hyper([a], [b], 0)", hyperexpand, "1")
  chk("hyper([a, b], [c], 1)", hyperexpand, "gamma(c)*gamma(-a - b + c)/(gamma(-a + c)*gamma(-b + c))")
  chk("hyper([a, b], [1 + a - b], -1)", hyperexpand, "gamma(a/2 + 1)*gamma(a - b + 1)/(gamma(a + 1)*gamma(a/2 - b + 1))")
  chk("hyper([1, a], [a + 1], z)/a", hyperexpand, "lerchphi(z, 1, a)")
  chk("hyper([1, 1, 1], [2, 2], z)*z", hyperexpand, "polylog(2, z)")
  chk("hyper([1], [b], z)", hyperexpand, "z^(1 - b)*(b - 1)*exp(z)*lowergamma(b - 1, z)")
  chk("hyper([a], [a + 1], z)", hyperexpand, "a*exp(-I*pi*a)*lowergamma(a, z*exp_polar(I*pi))/z^a")
  chk("hyper([1, 1], [2, 2], z)", hyperexpand, "(-log(z) + Ei(z))/z - EulerGamma/z")
  chk("hyper([-a], [], z)", hyperexpand, "(1 - z)^a")
  chk("hyper([a, -a], [Rational(1, 2)], z)", hyperexpand, "cos(2*a*asin(sqrt(z)))")
  chk("hyper([Rational(1, 2), 1], [Rational(3, 2)], z)", hyperexpand, "atanh(sqrt(z))/sqrt(z)")
  chk("hyper([1, 1], [Rational(3, 2)], z)", hyperexpand, "asin(sqrt(z))/(sqrt(z)*sqrt(1 - z))")
  chk("hyper([Rational(1, 2), Rational(1, 2)], [1], z)", hyperexpand, "2*elliptic_k(z)/pi")
  chk("hyper([-Rational(1, 2), Rational(1, 2)], [1], z)", hyperexpand, "2*elliptic_e(z)/pi")
  chk("hyper([], [b], z)", hyperexpand, "z^(1/2 - b/2)*besseli(b - 1, 2*sqrt(z))*gamma(b)")
  chk("hyper([a], [2*a], z)", hyperexpand, "2^(2*a - 1)*z^(1/2 - a)*exp(z/2)*besseli(a - 1/2, z/2)*gamma(a + 1/2)")
  chk("hyper([Rational(-1, 2)], [Rational(1, 2)], z)", hyperexpand, "I*sqrt(pi)*sqrt(z)*erf(I*sqrt(z)) + exp(z)")
  chk("hyper([Rational(1, 2)], [Rational(3, 2), Rational(3, 2)], z)", hyperexpand, "Shi(2*sqrt(z))/(2*sqrt(z))")
  chk("hyper([-3, 1], [2], z)", hyperexpand, "-z^3/4 + z^2 - 3*z/2 + 1")
  chk("hyper([3, a], [1, b], z)", hyperexpand, "(-a*b/2 + a*z/2 + 2*a)*hyper((a + 1,), (b,), z) + (a*b/2 - 2*a + 1)*hyper((a,), (b,), z)")
  chk("hyper([Rational(1, 2), a], [Rational(3, 2), a + 1], z)", hyperexpand, "-a*exp(-I*pi*a)*lowergamma(a, z*exp_polar(I*pi))/(z^a*(2*a - 1)) - I*sqrt(pi)*a*erf(I*sqrt(z))/(sqrt(z)*(2*a - 1))")
})

test_that("hyperexpand matches SymPy on Meijer G functions", {
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s))), want, label = s)
  chk("meijerg([[], []], [[0], []], -z)", hyperexpand, "exp(z)")
  chk("meijerg([[1, 1], []], [[1], [0]], z)", hyperexpand, "log(z + 1)")
  chk("meijerg([[1, 1], []], [[1], [1]], z)", hyperexpand, "z/(z + 1)")
  chk("meijerg([[], []], [[Rational(1, 2)], [0]], (z/2)**2)", hyperexpand, "sin(z)/sqrt(pi)")
  chk("meijerg([[], []], [[0], [Rational(1, 2)]], (z/2)**2)", hyperexpand, "cos(z)/sqrt(pi)")
  chk("meijerg([1], [], [], [0], z)", hyperexpand, "Piecewise((0, Abs(z) < 1), (1, 1/Abs(z) < 1), (meijerg(((1,), ()), ((), (0,)), z), True))")
  chk("meijerg([], [1], [0], [], z)", hyperexpand, "Piecewise((1, Abs(z) < 1), (0, 1/Abs(z) < 1), (meijerg(((), (1,)), ((0,), ()), z), True))")
  chk("meijerg([0, 2], [], [], [-1, 1], z)", hyperexpand, "Piecewise((0, Abs(z) < 1), (z*(1 - 1/z^2)/2, 1/Abs(z) < 1), (meijerg(((0, 2), ()), ((), (-1, 1)), z), True))")
  chk("meijerg([1], [], [a], [0, 0], z)", hyperexpand, "z^a*gamma(a)*hyper((a,), (a + 1, a + 1), -z)/gamma(a + 1)^2")
  chk("meijerg(((0, 1), ()), ((Rational(1, 2),), (0,)), z**2)", hyperexpand, "sqrt(pi)/sqrt(1 + z^(-2))")
  chk("meijerg([a], [], [b, a], [], z)", hyperexpand, "z^b*exp(z)*gamma(-a + b + 1)*uppergamma(a - b, z)")
  chk("meijerg([0], [], [0, 0], [], z)", hyperexpand, "exp(z)*expint(1, z)")
  chk("meijerg([a], [], [a, a, a - Rational(1, 2)], [], z)", hyperexpand, "-sqrt(pi)*z^(a - 1/2)*(2*(Si(2*sqrt(z)) - pi/2)*cos(2*sqrt(z)) - 2*sin(2*sqrt(z))*Ci(2*sqrt(z)))")
  chk("meijerg([a], [], [a, a - Rational(1, 2), a], [], z)", hyperexpand, "-sqrt(pi)*z^(a - 1/2)*(2*(Si(2*sqrt(z)) - pi/2)*cos(2*sqrt(z)) - 2*sin(2*sqrt(z))*Ci(2*sqrt(z)))")
  chk("meijerg([], [a], [a - 1, a - Rational(1, 2)], [], z)", hyperexpand, "-sqrt(pi)*z^(a - 1)*erf(sqrt(z)) + sqrt(pi)*z^(a - 1)")
  chk("meijerg([], [], [a/2], [-a/2], z)", hyperexpand, "exp(-I*pi*a/2)*besseli(a, 2*sqrt(z)*exp_polar(I*pi/2))")
  chk("meijerg([a], [b], [a], [b, a - 1], z)", hyperexpand, "(z^(a - 1)*exp(z) - z^(a - 1))/(gamma(-a + b)*gamma(a - b + 1))")
  chk("meijerg([], [], [a + b/2], [a, a - b/2, a + Rational(1, 2)], z)", hyperexpand, "(1/2)^b*z^a*exp(-I*pi*b)*besseli(b, 2*sqrt(2)*z^(1/4)*exp_polar(I*pi/2))*besselj(b, 2*sqrt(2)*z^(1/4)*exp_polar(I*pi/2))*gamma(b + 1)/(gamma(b/2 + 1/2)*gamma(b/2 + 1))")
  chk("meijerg([], [], [a], [b], z)", hyperexpand, "z^(a/2 + b/2)*exp(I*pi*(-a/2 + b/2))*besseli(a - b, 2*sqrt(z)*exp_polar(I*pi/2))")
  chk("meijerg([], [Rational(1, 2)], [a], [-a], z)", hyperexpand, "2^(2*a)*exp(z/2)*besseli(a, z/2)*gamma(a + 1)/(gamma(1/2 - a)*gamma(2*a + 1))")
  chk("meijerg([], [], [a, b], [], z)", hyperexpand, "z^(a/2 + b/2)*besseli(-a + b, 2*sqrt(z))*gamma(a - b)*gamma(-a + b + 1) + z^(a/2 + b/2)*besseli(a - b, 2*sqrt(z))*gamma(-a + b)*gamma(a - b + 1)")
  chk("meijerg([], [], [a, a + Rational(1, 2)], [b, b + Rational(1, 2)], z)", hyperexpand, "2^(-2*a + 2*b - 1)*sqrt(pi)*z^(a/2 + b/2)*(besseli(2*a - 2*b, 4*z^(1/4)) + besselj(2*a - 2*b, 4*z^(1/4)))*gamma(2*a - 2*b + 1)/(gamma(a - b + 1/2)*gamma(a - b + 1)) + sqrt(pi)*z^(a + 1/2)*(-2*2^(-2*a + 2*b - 3)*z^(-a/2 + b/2 - 1/2)*(besseli(2*a - 2*b + 2, 4*z^(1/4)) + besselj(2*a - 2*b + 2, 4*z^(1/4)))*gamma(2*a - 2*b + 2) - 2*2^(-2*a + 2*b - 2)*z^(-a/2 + b/2)*(besseli(2*a - 2*b + 2, 4*z^(1/4)) - besselj(2*a - 2*b + 2, 4*z^(1/4)))*((-a + b - 1/2)*(4*a - 4*b + 1)/(4*z) + (a^2/2 - a*b + a/4 + b^2/2 - b/4)/z + (a^2/2 - a*b + a/2 + b^2/2 - b/2 + 1/8)/z)*gamma(2*a - 2*b + 2) - 2*2^(-2*a + 2*b - 2)*z^(-a/2 + b/2 + 1/4)*((-a/2 + b/2)/z + (a - b + 1/4)/z)*(besseli(2*a - 2*b + 1, 4*z^(1/4)) - besselj(2*a - 2*b + 1, 4*z^(1/4)))*gamma(2*a - 2*b + 2))/(gamma(a - b + 1)*gamma(a - b + 3/2))")
  chk("meijerg([Rational(1, 2)], [], [0], [a, -a], z)", hyperexpand, "pi^(3/2)*a*besseli(-a, sqrt(z)*exp_polar(I*pi/2))*besseli(a, sqrt(z)*exp_polar(I*pi/2))/(sin(pi*(1 - a))*gamma(1 - a)*gamma(a + 1))")
  chk("meijerg([], [], [], [a, b], z)", hyperexpand, "0")
  chk("meijerg([a], [], [b, a + 1], [], z)", hyperexpand, "z^a*gamma(-a + b + 1) + z^b*(a - b - z)*exp(z)*gamma(-a + b + 1)*uppergamma(a - b, z)")
  chk("meijerg([1], [1 - a], [-a/2, -a/2 + Rational(1, 2)], [], 1/z)", hyperexpand, "(sqrt(z + 1) + 1)^a*gamma(-a/2)*gamma(1/2 - a/2)/(2^a*gamma(1 - a))")
  chk("meijerg([], [], [0], [], z)", hyperexpand, "exp(-z)")
  chk("meijerg([0], [], [0], [], z)", hyperexpand, "1/(z + 1)")
  chk("meijerg([], [1], [0, 0], [], z)", hyperexpand, "z*((log(z*exp_polar(I*pi)) - Ei(z*exp_polar(I*pi)))/z + EulerGamma/z) - log(z) - EulerGamma")
  chk("meijerg([1, 1], [], [1], [0], z*exp_polar(I*pi))", hyperexpand, "Piecewise((log(z - 1) + I*pi, Abs(z) > 1), (log(1 - z), True))")
})

test_that("hyperexpand matches SymPy on the cases of its test file", {
  skip_on_cran()
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s))), want, label = s)
  chk("hyper((), (), z)", hyperexpand, "exp(z)")
