test_that("cancel matches SymPy", {
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s))), want, label = s)
  chk("(x**2 - 1)/(x - 1)", cancel, "x + 1")
  chk("(x + 1)/(2*y)", cancel, "(x + 1)/(2*y)")
  chk("(2*x + 2)/(4*x)", cancel, "(x + 1)/(2*x)")
  chk("(x/2 + 1)/(3*y)", cancel, "(x + 2)/(6*y)")
  chk("(-x + 1)/(-y + 2)", cancel, "(x - 1)/(y - 2)")
  chk("1/x + 1/y", cancel, "(x + y)/(x*y)")
  chk("(x**2 + 2*x + 1)/(x**2 - 1)", cancel, "(x + 1)/(x - 1)")
  chk("sin(x)/x + 1", cancel, "(x + sin(x))/x")
  chk("(exp(x) - 1)/(exp(2*x) - 1)", cancel, "1/(exp(x) + 1)")
  chk("(x*y + x)/(y**2 - 1)", cancel, "x/(y - 1)")
  chk("(sqrt(2)*x + sqrt(2))/(x + 1)", cancel, "sqrt(2)")
  chk("(a*x + a)/(b*x + b)", cancel, "a/b")
  chk("x/(1 - x) + 1", cancel, "-1/(x - 1)")
  chk("(x**3 - y**3)/(x - y)", cancel, "x^2 + x*y + y^2")
  chk("(x + 0.5)/(2*x + 1)", cancel, "0.500000000000000")
  chk("Eq(x/(x + 1), 2)", cancel, "Eq(x/(x + 1), 2)")
  chk("(1 + I)/(x + I*x)", cancel, "1/x")
  chk("(x**2 - a**2)/(a - x)", cancel, "-a - x")
  chk("3/(6*x + 9)", cancel, "1/(2*x + 3)")
  chk("(z - a)/(b - z)", cancel, "(a - z)/(-b + z)")
  chk("(-a*z - 1)/(z**2 - 1)", cancel, "(-a*z - 1)/(z^2 - 1)")
  chk("f(x)/f(x)**2", cancel, "1/f(x)")
  chk("(x + y)**2/(x**2 - y**2)", cancel, "(x + y)/(x - y)")
  chk("(x + 0.5)/(x + 2.0)", cancel, "(1.0*x + 0.5)/(1.0*x + 2.0)")
  chk("(2.0*x + 1)/(4*x**2 - 1)", cancel, "2.0/(4.0*x - 2.0)")
})

