  chk("x/(x + 1) - 1", together, "-1/(x + 1)")
  chk("x/(x + 1) - 1", function(e) together(e, deep = TRUE), "-1/(x + 1)")
  chk("x/(x + 1) - 1", function(e) together(e, fraction = FALSE), "x/(x + 1) - 1")
  chk("3/(4*x) + 5/(6*x**2)", together, "(9*x + 10)/(12*x^2)")
  chk("3/(4*x) + 5/(6*x**2)", function(e) together(e, deep = TRUE), "(9*x + 10)/(12*x^2)")
  chk("3/(4*x) + 5/(6*x**2)", function(e) together(e, fraction = FALSE), "(9 + 10/x)/(12*x)")
})

test_that("unpolarify matches SymPy", {
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s))), want, label = s)
  chk("polar_lift(2 + I)", identity, "polar_lift(2 + I)")
  chk("polar_lift(2 + I)", unpolarify, "2 + I")
  chk("polar_lift(2 + I)", function(e) unpolarify(e, exponents_only = TRUE), "polar_lift(2 + I)")
  chk("polar_lift(x)", identity, "polar_lift(x)")
  chk("polar_lift(x)", unpolarify, "x")
  chk("polar_lift(x)", function(e) unpolarify(e, exponents_only = TRUE), "polar_lift(x)")
  chk("exp_polar(I*pi)*x", identity, "x*exp_polar(I*pi)")
  chk("exp_polar(I*pi)*x", unpolarify, "-x")
  chk("exp_polar(I*pi)*x", function(e) unpolarify(e, exponents_only = TRUE), "x*exp_polar(I*pi)")
  chk("exp_polar(2*I*pi)", identity, "exp_polar(2*I*pi)")
  chk("exp_polar(2*I*pi)", unpolarify, "1")
  chk("exp_polar(2*I*pi)", function(e) unpolarify(e, exponents_only = TRUE), "exp_polar(2*I*pi)")
  chk("sin(polar_lift(x))", identity, "sin(polar_lift(x))")
  chk("sin(polar_lift(x))", unpolarify, "sin(x)")
  chk("sin(polar_lift(x))", function(e) unpolarify(e, exponents_only = TRUE), "sin(polar_lift(x))")
  chk("gamma(exp_polar(I*pi)*z)", identity, "gamma(z*exp_polar(I*pi))")
  chk("gamma(exp_polar(I*pi)*z)", unpolarify, "gamma(-z)")
  chk("gamma(exp_polar(I*pi)*z)", function(e) unpolarify(e, exponents_only = TRUE), "gamma(z*exp_polar(I*pi))")
  chk("log(exp_polar(I*pi)*z)", identity, "log(z*exp_polar(I*pi))")
  chk("log(exp_polar(I*pi)*z)", unpolarify, "log(z*exp_polar(I*pi))")
  chk("log(exp_polar(I*pi)*z)", function(e) unpolarify(e, exponents_only = TRUE), "log(z*exp_polar(I*pi))")
  chk("(exp_polar(I*pi)*z)**(1/2)", identity, "sqrt(z)*exp_polar(I*pi/2)")
  chk("(exp_polar(I*pi)*z)**(1/2)", unpolarify, "I*sqrt(z)")
  chk("(exp_polar(I*pi)*z)**(1/2)", function(e) unpolarify(e, exponents_only = TRUE), "sqrt(z)*exp_polar(I*pi/2)")
  chk("(polar_lift(x))**y", identity, "polar_lift(x)^y")
  chk("(polar_lift(x))**y", unpolarify, "polar_lift(x)^y")
  chk("(polar_lift(x))**y", function(e) unpolarify(e, exponents_only = TRUE), "polar_lift(x)^y")
  chk("(polar_lift(-1)*z)**a", identity, "(z*exp_polar(I*pi))^a")
  chk("(polar_lift(-1)*z)**a", unpolarify, "(z*exp_polar(I*pi))^a")
  chk("(polar_lift(-1)*z)**a", function(e) unpolarify(e, exponents_only = TRUE), "(z*exp_polar(I*pi))^a")
  chk("exp_polar(I*pi)**2", identity, "exp_polar(2*I*pi)")
  chk("exp_polar(I*pi)**2", unpolarify, "1")
  chk("exp_polar(I*pi)**2", function(e) unpolarify(e, exponents_only = TRUE), "exp_polar(2*I*pi)")
  chk("exp_polar(x)**y", identity, "exp_polar(x*y)")
  chk("exp_polar(x)**y", unpolarify, "exp(x*y)")
  chk("exp_polar(x)**y", function(e) unpolarify(e, exponents_only = TRUE), "exp_polar(x*y)")
  chk("besselj(a, exp_polar(I*pi)*z)", identity, "besselj(a, z*exp_polar(I*pi))")
  chk("besselj(a, exp_polar(I*pi)*z)", unpolarify, "besselj(a, z*exp_polar(I*pi))")
  chk("besselj(a, exp_polar(I*pi)*z)", function(e) unpolarify(e, exponents_only = TRUE), "besselj(a, z*exp_polar(I*pi))")
  chk("hyper((1,), (2,), exp_polar(I*pi)*z)", identity, "hyper((1,), (2,), -z)")
  chk("hyper((1,), (2,), exp_polar(I*pi)*z)", unpolarify, "hyper((1,), (2,), -z)")
  chk("hyper((1,), (2,), exp_polar(I*pi)*z)", function(e) unpolarify(e, exponents_only = TRUE), "hyper((1,), (2,), -z)")
  chk("polar_lift(0)", identity, "polar_lift(0)")
  chk("polar_lift(0)", unpolarify, "0")
  chk("polar_lift(0)", function(e) unpolarify(e, exponents_only = TRUE), "0")
  chk("exp_polar(0)", identity, "exp_polar(0)")
  chk("exp_polar(0)", unpolarify, "1")
  chk("exp_polar(0)", function(e) unpolarify(e, exponents_only = TRUE), "1")
})

test_that("Abs and the incomplete gamma functions evaluate as in SymPy", {
  x <- Symbol("x", real = TRUE)
  chk <- function(s, f, want) expect_equal(sstr(f(sympify(s, locals = list(x = x)))), want, label = s)
  chk("Abs(1/z)", identity, "1/Abs(z)")
  chk("Abs(z**-2)", identity, "1/Abs(z^2)")
  chk("Abs(-x)", identity, "Abs(x)")
  chk("Abs(1 + I)", identity, "sqrt(2)")
  chk("Abs(2*z)", identity, "2*Abs(z)")
  chk("Abs(x**2)", identity, "x^2")
  chk("Abs(I*x)", identity, "Abs(x)")
  chk("Abs(exp(I*x))", identity, "1")
  chk("Abs(-z - 1)", identity, "Abs(z + 1)")
  chk("Abs(z)", identity, "Abs(z)")
  chk("Abs(3 + 4*I)", identity, "5")
  chk("Abs(sqrt(2)*I + 1)", identity, "sqrt(3)")
  chk("Abs(x*z)", identity, "Abs(x*z)")
  chk("Abs(z**3)", identity, "Abs(z^3)")
  chk("Abs(exp(z))", identity, "exp(re(z))")
  chk("Abs(2**z)", identity, "2^re(z)")
  chk("Abs(x + I)", identity, "sqrt(x^2 + 1)")
  chk("Abs(sign(x))", identity, "Abs(sign(x))")
  chk("Abs(exp_polar(I*pi)*z)", identity, "Abs(z)")
  chk("uppergamma(0, z)", identity, "expint(1, z)")
  chk("uppergamma(-1, z)", identity, "expint(2, z)/z")
  chk("uppergamma(2, z)", identity, "(z + 1)*exp(-z)")
  chk("uppergamma(Rational(3, 2), z)", identity, "sqrt(z)*exp(-z) + sqrt(pi)*erfc(sqrt(z))/2")
  chk("uppergamma(-Rational(1, 2), z)", identity, "-2*sqrt(pi)*erfc(sqrt(z)) + 2*exp(-z)/sqrt(z)")
  chk("lowergamma(2, z)", identity, "-(z + 1)*exp(-z) + 1")
  chk("lowergamma(Rational(3, 2), z)", identity, "sqrt(pi)*(-2*sqrt(z)*exp(-z)/sqrt(pi) + erf(sqrt(z)))/2")
  chk("lowergamma(-Rational(1, 2), z)", identity, "-2*sqrt(pi)*erf(sqrt(z)) - 2*exp(-z)/sqrt(z)")
  chk("lowergamma(a, z*exp_polar(2*I*pi))", identity, "exp(2*I*pi*a)*lowergamma(a, z)")
  chk("uppergamma(a, z*exp_polar(2*I*pi))", identity, "(1 - exp(2*I*pi*a))*gamma(a) + exp(2*I*pi*a)*uppergamma(a, z)")
  chk("uppergamma(0, x)", identity, "expint(1, x)")
})

